from kd_common import *
i=7
Z=lambda q,a:[('z',q),('b',a)]
def stool(): return '<path d="M-20 0 l6 -20 h28 l6 20 M0 -20 v20" stroke="#5a3a1a" stroke-width="4" fill="none"/><ellipse cy="-22" rx="18" ry="5" fill="#7a3b1f"/>'
def banana(): return '<path d="M0 0 v-60" stroke="#6a9a3a" stroke-width="10"/><path d="M0 -50 q-26 -10 -30 -30 M0 -56 q26 -10 30 -30" stroke="#2f8a3a" stroke-width="6" fill="none"/>'
def pots(): return '<ellipse cx="-10" cy="-8" rx="10" ry="8" fill="#c9a227"/><ellipse cx="-10" cy="-24" rx="8" ry="7" fill="#c9a227"/>'
fw=foreword(i,['A Kodava wedding has no fire, no seven steps and no priest. The couple sit on <b>three-legged stools</b>, elders bless them before the lamp, the two clans speak an ancient dialogue to join them, and at the end the bride draws water from a well while the groom’s family dance around her. Life’s great rites in Kodagu belong to the family and the clan.',
 'This part covers the rites of birth and childhood, the full Kodava wedding (mangala) in its main stages, and the rites of death, as they are described by Kodava writers and the press.',
 'The ainmane, where many rites happen, is in '+L('/kodagu/ainmane/','Part 7')+'. Next: '+L('/kodagu/village-deities/','village deities')+'.'],Z('No priest at all?','Not for the core rites. The elders conduct them.'))
gl=glance([('Wedding','Mangala, usually a two-day affair'),('No','Priest, fire (agni) or seven steps'),('Seats','Mukkāli, three-legged stools'),('Blessing','Elders and guests bless the couple: the muhūrta'),('Joining','Sammanda koḍupo: dialogue between the clans’ spokesmen (aruvas)'),('Banana stems','Bāḷe birud: cut with the oḍi katti'),('Water','Gaṅgā pūje (nīr eḍpo): bride fetches water'),('Music','The vālaga band; dancing late'),('Death','Guided by elders; the dead join the ancestors'),('Where','Ainmane, home or a Samāja hall')],
 S('A bride and groom seated on three-legged stools before a lamp with elders blessing',g(220,210,1.2,stool())+g(340,210,1.2,stool())+g(220,180,1.1,kodava_woman('#c0392b'))+g(340,180,1.1,kodava_man('#f4f1ea'))+g(280,120,.8,hanging_lamp())+g(100,215,1,kodava_man())+g(460,215,1,kodava_woman('#2a9d6f')),'#fff3cf',215),Z('Why three legs?','A three-legged stool stands firm on uneven ground. Make of that what you will.'),'Family, clan, <b>and the lamp</b>.')
birth=reading('birth','BIRTH','Welcoming a child',S('A mother with a baby, an elder lighting the lamp, a small gun',g(170,215,1.4,kodava_woman())+'<ellipse cx="182" cy="150" rx="12" ry="8" fill="#f4f1ea"/>'+g(300,215,1.2,lamp())+g(430,215,1.4,kodava_man()),'#fff3cf',215),
 ['<b>Care.</b> After childbirth the mother rests for a period of care at home.','<b>Announcing a son.</b> Old accounts say the birth of a boy was announced with a gunshot; some say a bow and arrow were given. (As described.)','<b>Naming.</b> A naming ceremony follows, with the clan name first.','<b>Rights.</b> Every rite ties the child to the okka and ainmane.','<b>Change.</b> Today most births are in hospitals, but the family rites remain.'],Z('A gun for a baby?','A salute, not a toy. An old custom, now rare.'),'A new name <b>in the clan</b>.')
eve=reading('eve','THE DAY BEFORE','Ūrkūḍuvō and the bangles',S('Relatives gathering at a house with a feast; a woman fitting bangles on the bride',g(150,215,1.2,kodava_woman('#c0392b'))+'<circle cx="170" cy="168" r="6" fill="none" stroke="#e0a800" stroke-width="3"/>'+g(210,215,1.1,kodava_woman('#2a9d6f'))+g(400,200,1.2,ainmane(140)),'#fff3cf',215),
 ['<b>Ūrkūḍuvō.</b> On the eve, the village and relatives gather to prepare: the ūrkūḍuvō.','<b>Bāḷe iḍuva.</b> The bride is given bangles in a ceremony.','<b>Separately.</b> Traditionally each side held its own rites at its own house first.','<b>Single muhūrta.</b> Bride and groom were first blessed separately: the “single muhūrta”.','<b>Feast.</b> Pork, rice and drink are part of the feast. (Some Samājas now restrict liquor.)'],Z('Two separate weddings?','In the old form, yes: first each at home, then together.'),'The village <b>comes to help</b>.')
bale=reading('bale','BĀḶE BIRUD','Cutting the banana stems',S('The groom cuts a banana stem with a broad knife; stems line the path',''.join(g(180+k*70,215,1,banana()) for k in range(5))+g(110,215,1.6,kodava_man('#f4f1ea'))+'<path d="M130 150 l40 -8" stroke="#9a9a9a" stroke-width="6"/>','#d8e8c8',215),
 ['<b>The stems.</b> Banana stems, decorated with flowers, are set along the path.','<b>The cut.</b> The groom, or a family member, cuts through them with the oḍi katti.','<b>Meaning.</b> Commonly explained as cutting through obstacles. (Common explanation.)','<b>Groom’s dress.</b> He wears a white kupya, chele, turban, pīcce katti and a jasmine garland.','<b>Welcome.</b> The bride’s mother feeds him milk, rice and sugar.'],Z('One stroke?','That is the ideal. The crowd counts.'),'Through the stems, <b>to the bride</b>.')
muh=reading('muhurta','DAMPATI MUHŪRTA','The blessing',S('Bride and groom on stools; guests sprinkle rice on them before the lamp',g(220,210,1.2,stool())+g(340,210,1.2,stool())+g(220,180,1.1,kodava_woman('#c0392b'))+g(340,180,1.1,kodava_man('#f4f1ea'))+''.join(f'<circle cx="{200+k*20}" cy="{90+(k%3)*8}" r="2.5" fill="#f4f1ea"/>' for k in range(8))+g(100,215,1,kodava_man())+g(460,215,1,kodava_woman('#2a9d6f')),'#fff3cf',215),
 ['<b>The dais.</b> The couple sit on <b>mukkālis</b> on a decorated dais.','<b>The groom.</b> He sprinkles rice towards the lamp, walks three times round the stool and sits.','<b>Blessing.</b> Elders and guests come one by one, sprinkle rice and bless them, offering milk and gifts.','<b>Kāveramma.</b> The families seek the blessing of Kāverī.','<b>Garlands.</b> He helps her rise and they exchange garlands.'],Z('Does everyone bless?','Hundreds of guests. It takes a long time.'),'Rice, milk <b>and many hands</b>.')
samm=reading('sammanda','SAMMANDA','The clans speak',S('Two elders face each other holding a coin; families listen',g(200,215,1.6,kodava_man())+g(360,215,1.6,kodava_man('#3a3a3a'))+'<circle cx="280" cy="150" r="8" fill="#e0a800"/>'+g(100,215,.9,kodava_woman())+g(470,215,.9,kodava_woman('#2a9d6f')),'#fff3cf',215),
 ['<b>Sammanda koḍupo.</b> The spokesmen (aruvas) of the two clans exchange a formal, ancient dialogue.','<b>Rights.</b> The bride is given rights in her husband’s house and clan.','<b>The coin.</b> A gold coin is given as a pledge to look after her; it is tied and kept. (As described.)','<b>This is the wedding.</b> The dialogue, not a fire rite, solemnises the union.','<b>Records.</b> In the old days the sammanda was the legal proof of marriage.'],Z('Like a contract?','A spoken contract between clans, witnessed by everyone.'),'The words <b>that make it binding</b>.')
ganga=reading('ganga','GAṄGĀ PŪJE','The bride fetches water',S('The bride walks from a well with pots on her head as relatives dance around her',g(120,215,1.4,'<rect x="-30" y="-30" width="60" height="30" fill="#9a8a7a"/><ellipse cy="-30" rx="30" ry="6" fill="#4aa3df"/>')+g(280,215,1.8,kodava_woman('#c0392b'))+g(282,118,1.2,pots())+''.join(g(380+k*50,215,.9,kodava_man()) for k in range(3)),'#20243a',215),
 ['<b>Nīr eḍpo.</b> At the end of the day the bride draws water from the well at her new home: the Gaṅgā pūje or nīr eḍpo, “fetching water”.','<b>The walk.</b> She carries the pots on her head with a head-rest, taking small, careful steps.','<b>The teasing.</b> The groom’s family dance round her and try to delay her.','<b>Meaning.</b> She shows patience and strength, and takes up her place in the household. (Common explanation.)','<b>All night.</b> The dancing may go on to the early hours.'],Z('Do they make it hard?','Very. That is the fun.'),'The first water <b>of a new home</b>.')
dance=reading('feast','FEAST AND DANCE','Vālaga and pork',S('A band playing while guests dance; tables of food',''.join(g(80+k*60,215,.9,person('#f4f1ea')) for k in range(3))+''.join(g(320+k*60,215,1,[kodava_man(),kodava_woman()][k%2]) for k in range(4)),'#fff3cf',215),
 ['<b>Vālaga.</b> The band plays outside; anyone who wants to dance, dances.','<b>Food.</b> Pork curry, rice and kaḍambuṭṭ are central.','<b>Drink.</b> Alcohol was traditional; some Kodava associations now urge a ban at weddings.','<b>Short.</b> Kodava weddings are shorter than many Indian weddings.','<b>Mixed weddings.</b> Many couples combine Kodava rites with other customs.'],Z('Is the band essential?','No band, no Kodava wedding.'),'Dance <b>till the pots are home</b>.')
death=reading('death','DEATH','The last rites',S('Elders around a lamp; a field with paddy; a quiet procession',g(280,215,1.4,lamp())+''.join(g(120+k*80,215,1,kodava_man('#f4f1ea')) for k in range(2))+''.join(g(380+k*60,215,1,kodava_man('#f4f1ea')) for k in range(2)),'#e3eaf3',215),
 ['<b>The elders.</b> Death rites (cāvu) are conducted by family elders.','<b>News.</b> Old accounts say a death was announced by gunshots. (As described.)','<b>Holy water.</b> A sip of Kāverī tīrtha is given to the dying.','<b>Ancestors.</b> After the rites the dead join the ancestors (kāraṇas) honoured at the ainmane.','<b>Clan.</b> Special rites also govern widows and children’s clan rights.'],Z('Burial or cremation?','Customs differ by family and period; we do not generalise.'),'From the clan <b>to the ancestors</b>.')
endp=end(i,['<b>Birth.</b> A new name in the clan.','<b>Wedding.</b> No priest or fire; mukkāli, muhūrta, sammanda, bāḷe birud, Gaṅgā pūje.','<b>Feast.</b> Vālaga, pork and dance.','<b>Death.</b> Elders lead; the dead become ancestors.'],'Part 9 is the village deities.','Joined by the clans')
src=sources([('Wedding:','Coorg Tourism Info, “Traditional Kodava mangala”; Kodava heritage site (wedding day rituals, groom’s dress, dampati muhūrta, sammanda koḍupo); Deccan Herald, “Old Kodava weddings stage a comeback” (nīr eḍpo); Deccan Chronicle and other reports (bāḷe iḍuva, bāḷe birud, Gaṅgā pūje); The Knot (aruvas, Kāveramma, no priest); Deccan Herald on proposals to ban liquor.'),('Death and clan rites:','Kodava heritage site (cāvu, kole aḍaṅga sammanda).')],'birth customs (gun, bow), the gold-coin detail and the gunshot at death are as described in community accounts; burial or cremation is left general.','Rites vary by family and region.')
finish(i,'PART 8 OF 12 · BIRTH · MANGALA · DEATH',covart('Bride and groom on three-legged stools before a hanging lamp',g(170,190,1,stool())+g(270,190,1,stool())+g(170,165,1,kodava_woman('#c0392b'))+g(270,165,1,kodava_man('#f4f1ea'))+g(220,110,.6,hanging_lamp())),'Joined by the clans',
 'Kodava <b>life rites</b>: birth, the <b>mangala</b> wedding with its mukkālis, sammanda and Gaṅgā pūje, and the rites of death that make the dead ancestors.',
 'Kodava life rites explained and illustrated: birth and naming, the Kodava wedding (ūrkūḍuvō, bāḷe birud, dampati muhūrta on mukkālis, sammanda koḍupo, Gaṅgā pūje), feast and vālaga, and death rites.',
 [fw,gl,birth,eve,bale,muh,samm,ganga,dance,death,endp,src])
